package com.app.service;
import com.app.dto.SocietyAttendanceDtos.*; import com.app.entity.*; import com.app.exception.*; import com.app.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*; import java.util.function.Function; import java.util.stream.Collectors;
@Service @RequiredArgsConstructor public class SocietyAttendanceService {private final AccountRepository accounts;private final UserRepository users;private final SocietyRosterAssignmentRepository roster;private final SocietyAttendanceRepository attendance;private final SocietyAgencyWorkerRepository workers;private final SocietyAgencyRepository agencies;
 @Transactional(readOnly=true) public List<AttendanceRow> day(Long accountId,LocalDate date){society(accountId);Map<Long,SocietyAttendance> saved=attendance.findByAccountIdAndAttendanceDate(accountId,date).stream().collect(Collectors.toMap(x->x.getRosterAssignment().getId(),Function.identity()));return roster.findByAccountIdAndActiveTrueOrderByPostNameAsc(accountId).stream().filter(x->!date.isBefore(x.getEffectiveFrom())&&(x.getEffectiveTo()==null||!date.isAfter(x.getEffectiveTo()))).map(x->map(x,saved.get(x.getId()))).toList();}
 @Transactional public List<AttendanceRow> saveBulk(Long accountId,Long userId,BulkRequest request){Account account=society(accountId);User user=users.findById(userId).orElseThrow(()->new ValidationException("User not found"));Set<Long> ids=new HashSet<>();Set<Long> replacements=new HashSet<>();for(AttendanceEntry e:request.getEntries()){if(!ids.add(e.getRosterAssignmentId()))throw new ValidationException("Duplicate roster assignment in attendance submission");SocietyRosterAssignment r=roster.findByAccountIdAndIdAndActiveTrue(accountId,e.getRosterAssignmentId()).orElseThrow(()->new ResourceNotFoundException("Roster assignment not found"));if(request.getAttendanceDate().isBefore(r.getEffectiveFrom())||(r.getEffectiveTo()!=null&&request.getAttendanceDate().isAfter(r.getEffectiveTo())))throw new ValidationException("Roster assignment is not active on attendance date");SocietyAgencyWorker replacement=null;if(e.getReplacementAgencyWorkerId()!=null){if(r.getAgencyWorker()==null)throw new ValidationException("Replacement workers apply only to agency assignments");replacement=workers.findByAccountIdAndIdAndActiveTrue(accountId,e.getReplacementAgencyWorkerId()).orElseThrow(()->new ResourceNotFoundException("Replacement worker not found"));if(!replacement.getAgency().getId().equals(r.getAgencyWorker().getAgency().getId()))throw new ValidationException("Replacement must belong to the same agency");if(replacement.getId().equals(r.getAgencyWorker().getId())||!replacements.add(replacement.getId()))throw new ValidationException("Replacement worker is invalid or already assigned");}SocietyAttendance row=attendance.findByRosterAssignmentIdAndAttendanceDate(r.getId(),request.getAttendanceDate()).orElseGet(()->SocietyAttendance.builder().account(account).rosterAssignment(r).attendanceDate(request.getAttendanceDate()).build());row.setStatus(e.getStatus());row.setCheckIn(e.getCheckIn());row.setCheckOut(e.getCheckOut());row.setReplacementAgencyWorker(replacement);row.setNotes(clean(e.getNotes()));row.setRecordedBy(user);attendance.save(row);}return day(accountId,request.getAttendanceDate());}
 @Transactional(readOnly=true) public List<AgencyShortage> shortages(Long accountId,LocalDate date){society(accountId);List<SocietyAttendance> rows=attendance.findByAccountIdAndAttendanceDate(accountId,date);return agencies.findByAccountIdAndActiveTrueOrderByNameAsc(accountId).stream().map(a->{List<SocietyAttendance> own=rows.stream().filter(x->x.getRosterAssignment().getAgencyWorker()!=null&&x.getRosterAssignment().getAgencyWorker().getAgency().getId().equals(a.getId())).toList();long present=own.stream().filter(x->Set.of("PRESENT","LATE","HALF_DAY").contains(x.getStatus())).count();long replacement=own.stream().filter(x->x.getReplacementAgencyWorker()!=null).count();return AgencyShortage.builder().agencyId(a.getId()).agencyName(a.getName()).required(a.getRequiredHeadcount()).present(present).replacements(replacement).shortage(Math.max(0,a.getRequiredHeadcount()-present-replacement)).build();}).toList();}
 private AttendanceRow map(SocietyRosterAssignment r,SocietyAttendance a){boolean direct=r.getStaff()!=null;SocietyAgency agency=direct?null:r.getAgencyWorker().getAgency();return AttendanceRow.builder().id(a==null?null:a.getId()).rosterAssignmentId(r.getId()).assigneeName(direct?r.getStaff().getStaffName():r.getAgencyWorker().getWorkerName()).assigneeType(direct?"DIRECT":"AGENCY").agencyId(agency==null?null:agency.getId()).agencyName(agency==null?null:agency.getName()).shiftName(r.getShift().getName()).scheduledStart(r.getShift().getStartTime()).scheduledEnd(r.getShift().getEndTime()).postName(r.getPostName()).status(a==null?"NOT_SCHEDULED":a.getStatus()).checkIn(a==null?null:a.getCheckIn()).checkOut(a==null?null:a.getCheckOut()).replacementAgencyWorkerId(a==null||a.getReplacementAgencyWorker()==null?null:a.getReplacementAgencyWorker().getId()).replacementWorkerName(a==null||a.getReplacementAgencyWorker()==null?null:a.getReplacementAgencyWorker().getWorkerName()).notes(a==null?null:a.getNotes()).build();}
 private Account society(Long id){return accounts.findById(id).filter(a->a.getAccountType()==AccountType.SOCIETY&&Boolean.TRUE.equals(a.getActive())).orElseThrow(()->new ResourceNotFoundException("Society not found"));}private String clean(String s){return s==null||s.isBlank()?null:s.trim();}
}
